static class Program
{
 static int passed,failed;
 static void Check(bool value,string message="assertion"){if(!value)throw new Exception(message);}
 static void Eq<T>(T expected,T actual){if(!Equals(expected,actual))throw new Exception($"expected {expected}, got {actual}");}
 static void Test(string name,Action action){Reset();ExtraReset();try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+" "+e);}}
 static void ExtraReset(){GameStates.ExiledAnimate=false;CustomWinnerHolder.WinnerTeam=CustomWinner.Default;AssassinGuardFragment.NowState=AssassinMeeting.WaitMeeting;AssassinGuardFragment.Calls=0;AssassinGuardFragment.AddRole=null;ReportDeadBodyPatch.IgnoreBodyids.Clear();Options.MadCanSeeImpostor.Value=1;RaccoonParent.ChildKillOnMeetingIfGrabbing=true;RaccoonParent.OptionKillOnMeetingIfGrabbing.Value=1;Professional.RoleInfo.Setup();}
 static Professional Pro(){var p=P(1,CustomRoles.Professional);p.inVent=false;return new Professional(p);}
 static bool PressPro(Professional role){bool adjust=true;bool? cooldown=false;((IUsePhantomButton)role).OnClick(ref adjust,ref cooldown);return cooldown==true;}
 static PlayerControl P(byte id,CustomRoles role=CustomRoles.Crewmate,float x=0){var p=new PlayerControl{PlayerId=id,OwnerId=id+100,Role=role,inVent=true};p.transform.position=new Vector3(x,0);PlayerCatch.All.Add(p);return p;}
 static void Reset(){Hunter.ResetForGame();Hunter.achievements.Clear();Hunter.Load();PlayerCatch.All.Clear();CustomRoleManager.AllActiveRoles.Clear();PlayerState.Reset();OptionItem.All.Clear();Hunter.RoleInfo.Setup();TownOfHost.Main.AllPlayerSpeed.Clear();LateTask.Jobs.Clear();CustomRoleManager.Accept=true;CustomRoleManager.Throw=false;CustomRoleManager.Validate=true;CustomRoleManager.Attempts=0;CustomRoleManager.Observe=null;CheckMurderPatch.TimeSinceLastKill.Clear();AmongUsClient.Instance=new();GameStates.IsInTask=true;GameStates.IsMeeting=GameStates.CalledMeeting=false;Options.CurrentGameMode=CustomGameMode.Standard;Options.firstturnmeeting=Options.IsStandardHAS=false;MeetingStates.FirstMeeting=false;Options.HideAndSeekKillDelayTimer=0;MeetingHud.Instance=null;GameOptionsManager.Instance=new();ShipStatus.Instance=null;PlayerControl.LocalPlayer=null;Time.time=0;Time.fixedDeltaTime=.02f;MiraVentLock.Reset();VentilationSystemUpdateSystemPatch.NowVentId.Clear();Hazel.MessageWriter.Created.Clear();RPC.SoundsPlayed=0;}
 static (PlayerControl,VentilationSystem) World(){var host=P(1);host.AmOwner=true;PlayerControl.LocalPlayer=host;var player=P(2);ShipStatus.Instance=new();var sys=new VentilationSystem();ShipStatus.Instance.Systems[SystemTypes.Ventilation]=sys;sys.PlayersInsideVents[2]=6;sys.PlayersCleaningVents[20]=2;ShipStatus.Instance.AllVents=new[]{new Vent{Id=6,NearbyVents=new[]{new Vent{Id=7},new Vent{Id=5},new Vent{Id=3}}},new Vent{Id=5,NearbyVents=new[]{new Vent{Id=4}}},new Vent{Id=7},new Vent{Id=3},new Vent{Id=4}};return(player,sys);}
 static MiraVentLock.Correction? Prefix(VentilationSystem sys,byte id,ref Op op,ref byte to,bool run=true){MiraVentLock.NativeOperationPatch.Prefix(sys,id,ref op,ref to,out var c,run);return c;}
 static void Complete(MiraVentLock.Correction? c,bool run=true)=>MiraVentLock.NativeOperationPatch.Postfix(c,run);
 static (Hunter,Hunter,PlayerControl) Hunters(){var a=new Hunter(P(1,CustomRoles.Hunter));var b=new Hunter(P(2,CustomRoles.Hunter));var witness=P(5,CustomRoles.Crewmate,.5f);var victimA=P(3,CustomRoles.Crewmate,1);var victimB=P(4,CustomRoles.Crewmate,1);bool animate=true;a.CheckShapeshift(victimA,ref animate);b.CheckShapeshift(victimB,ref animate);a.OnFixedUpdate(a.Player);b.OnFixedUpdate(b.Player);return(a,b,witness);}
 static void Main()
 {
  var edges=new[]{(6,7),(6,5),(5,4),(4,3),(3,9),(9,10),(10,11),(10,8),(1,2)};
  foreach(var (from,to) in edges){Test($"Mira edge {from}->{to}",()=>Check(MiraVentRules.IsBlocked(from,to)));Test($"Mira reverse edge {to}->{from}",()=>Check(MiraVentRules.IsBlocked(to,from)));}
  foreach(var (from,to) in new[]{(0,1),(2,3),(6,3),(4,9),(7,8),(0,11),(6,6),(-1,2),(1,-2),(256,2),(2,256)})Test($"Mira unblocked/invalid {from}:{to}",()=>Check(!MiraVentRules.IsBlocked(from,to)));
  Test("native signature is verified",()=>Check(MiraVentLock.ApiAvailable));
  Test("null native signature rejected",()=>Check(!MiraVentLock.IsCompatible(null)));
  Test("different native signature rejected",()=>Check(!MiraVentLock.IsCompatible(typeof(string).GetMethod("ToString",Type.EmptyTypes))));
  Test("no ship is a safe inactive state",()=>Check(!MiraVentLock.Active));
  Test("no options is a safe inactive state",()=>{World();GameOptionsManager.Instance=null;Check(!MiraVentLock.Active);});
  foreach(byte map in new byte[]{0,2,3,4,5})Test("other map inactive "+map,()=>{World();GameOptionsManager.Instance.CurrentGameOptions.MapId=map;Check(!MiraVentLock.Active);});
  foreach(string condition in new[]{"nonhost","meeting","called","not-task","mode"})Test("Mira scope gate "+condition,()=>{var(p,sys)=World();if(condition=="nonhost")AmongUsClient.Instance.AmHost=false;if(condition=="meeting")GameStates.IsMeeting=true;if(condition=="called")GameStates.CalledMeeting=true;if(condition=="not-task")GameStates.IsInTask=false;if(condition=="mode")Options.CurrentGameMode=CustomGameMode.HideAndSeek;Op op=Op.Move;byte to=7;var c=Prefix(sys,p.PlayerId,ref op,ref to);Check(c==null);Eq(Op.Move,op);Eq((byte)7,to);Complete(c);Eq(0,p.MyPhysics.Boots.Count);});
  Test("remote blocked hop uses native exit and standard boot only",()=>{var(p,sys)=World();Op op=Op.Move;byte to=7;var c=Prefix(sys,2,ref op,ref to);Eq(Op.Exit,op);Eq((byte)6,to);Check(c.HasValue);sys.PerformVentOp(2,op,to,new());Complete(c);Eq(1,sys.Applied.Count);Check(!sys.PlayersInsideVents.ContainsKey(2));Check(p.MyPhysics.Boots.SequenceEqual(new[]{6}));Eq((byte)6,VentilationSystemUpdateSystemPatch.NowVentId[2]);Eq(1,sys.PlayersCleaningVents.Count);Eq((byte)2,sys.PlayersCleaningVents[20]);Eq(0,AmongUsClient.Instance.Packets.Count);Eq(0,Hazel.MessageWriter.Created.Count);});
  Test("unblocked hop retains original operation",()=>{var(p,sys)=World();Op op=Op.Move;byte to=3;var c=Prefix(sys,2,ref op,ref to);Check(c==null);Eq(Op.Move,op);Eq((byte)3,to);sys.PerformVentOp(2,op,to,new());Complete(c);Eq((byte)3,sys.PlayersInsideVents[2]);Eq(0,p.MyPhysics.Boots.Count);});
  foreach(Op kind in new[]{Op.StartCleaning,Op.StopCleaning,Op.Enter,Op.Exit,Op.BootImpostors,(Op)99})Test("non-move operation retained "+kind,()=>{var(_,sys)=World();Op op=kind;byte to=7;Check(Prefix(sys,2,ref op,ref to)==null);Eq(kind,op);Eq((byte)7,to);});
  foreach(string condition in new[]{"null-system","wrong-system","no-player","dead","disconnected","outside","no-link","null-vents","no-vent-system"})Test("Mira bad state safe "+condition,()=>{var(p,sys)=World();byte id=2;if(condition=="null-system")sys=null;if(condition=="wrong-system")sys=new(){Pointer=new(87)};if(condition=="no-player")id=30;if(condition=="dead")p.Data.IsDead=true;if(condition=="disconnected")p.Data.Disconnected=true;if(condition=="outside")sys.PlayersInsideVents.Clear();if(condition=="no-link")ShipStatus.Instance.AllVents[0].NearbyVents=Array.Empty<Vent>();if(condition=="null-vents")ShipStatus.Instance.AllVents=null;if(condition=="no-vent-system")ShipStatus.Instance.Systems.Clear();Op op=Op.Move;byte to=7;Check(Prefix(sys,id,ref op,ref to)==null);Eq(Op.Move,op);});
  Test("native wrapper identity uses Pointer, not managed reference",()=>{var(_,sys)=World();var wrapper=new VentilationSystem{Pointer=sys.Pointer,PlayersInsideVents=sys.PlayersInsideVents};Op op=Op.Move;byte to=7;Check(Prefix(wrapper,2,ref op,ref to).HasValue);});
  Test("other Harmony suppression respected before native operation",()=>{var(_,sys)=World();Op op=Op.Move;byte to=7;Check(Prefix(sys,2,ref op,ref to,false)==null);Eq(Op.Move,op);});
  Test("later Harmony suppression prevents correction RPC",()=>{var(p,sys)=World();Op op=Op.Move;byte to=7;var c=Prefix(sys,2,ref op,ref to);Complete(c,false);Eq(0,p.MyPhysics.Boots.Count);});
  foreach(string stop in new[]{"game","ship","dead","disconnect","meeting","lost-host"})Test("stale Mira correction cancelled "+stop,()=>{var(p,sys)=World();Op op=Op.Move;byte to=7;var c=Prefix(sys,2,ref op,ref to);if(stop=="game")AmongUsClient.Instance.GameId++;if(stop=="ship")ShipStatus.Instance.Pointer=new(88);if(stop=="dead")p.Data.IsDead=true;if(stop=="disconnect")p.Data.Disconnected=true;if(stop=="meeting")GameStates.IsMeeting=true;if(stop=="lost-host")AmongUsClient.Instance.AmHost=false;Complete(c);Eq(0,p.MyPhysics.Boots.Count);});
  Test("correction failure does not replay or throw",()=>{var(p,sys)=World();p.MyPhysics.ThrowOnBoot=true;Op op=Op.Move;byte to=7;var c=Prefix(sys,2,ref op,ref to);Complete(c);p.MyPhysics.ThrowOnBoot=false;Complete(c);Eq(0,p.MyPhysics.Boots.Count);Time.time=.3f;Complete(c);Eq(1,p.MyPhysics.Boots.Count);});
  Test("per-player correction rate is bounded",()=>{var(p,sys)=World();for(int i=0;i<100;i++){Op op=Op.Move;byte to=7;Complete(Prefix(sys,2,ref op,ref to));}Eq(1,p.MyPhysics.Boots.Count);Time.time=.3f;Op last=Op.Move;byte dest=7;Complete(Prefix(sys,2,ref last,ref dest));Eq(2,p.MyPhysics.Boots.Count);});
  Test("multiple remote players corrected independently",()=>{var(p,sys)=World();var other=P(3);sys.PlayersInsideVents[3]=5;Op op=Op.Move;byte to=7;Complete(Prefix(sys,2,ref op,ref to));op=Op.Move;to=4;Complete(Prefix(sys,3,ref op,ref to));Check(p.MyPhysics.Boots.SequenceEqual(new[]{6}));Check(other.MyPhysics.Boots.SequenceEqual(new[]{5}));});
  Test("scene reset drops correction throttle",()=>{var(p,sys)=World();Op op=Op.Move;byte to=7;Complete(Prefix(sys,2,ref op,ref to));MiraVentLock.Reset();op=Op.Move;to=7;Complete(Prefix(sys,2,ref op,ref to));Eq(2,p.MyPhysics.Boots.Count);});
  Test("local host button vetoes blocked edge",()=>{World();bool result=true;Check(!MiraVentLock.LocalMovePatch.Prefix(new(){Id=6},new(){Id=7},ref result,true));Check(!result);});
  Test("local allowed edge remains available",()=>{World();bool result=true;Check(MiraVentLock.LocalMovePatch.Prefix(new(){Id=6},new(){Id=3},ref result,true));Check(result);});
  Test("local nonhost never enforces on vanilla host",()=>{World();AmongUsClient.Instance.AmHost=false;bool result=true;Check(MiraVentLock.LocalMovePatch.Prefix(new(){Id=6},new(){Id=7},ref result,true));Check(result);});
  Test("local earlier button veto retained",()=>{World();bool result=false;Check(!MiraVentLock.LocalMovePatch.Prefix(new(){Id=6},new(){Id=3},ref result,false));Check(!result);});
  Test("lease duplicate targets are idempotent",()=>{var leases=new HunterVisionLeases();var a=new object();leases.Replace(a,new byte[]{1,1,1});leases.Replace(a,new byte[]{1,1});leases.Release(a);Check(!leases.Contains(1));});
  Test("lease overlap survives another owner release",()=>{var leases=new HunterVisionLeases();var a=new object();var b=new object();leases.Replace(a,new byte[]{5});leases.Replace(b,new byte[]{5});leases.Release(a);Check(leases.Contains(5));leases.Release(b);Check(!leases.Contains(5));});
  Test("lease replacement removes only departed targets",()=>{var leases=new HunterVisionLeases();var owner=new object();leases.Replace(owner,new byte[]{1,2});leases.Replace(owner,new byte[]{2,3});Check(!leases.Contains(1)&&leases.Contains(2)&&leases.Contains(3));});
  Test("lease old instance cannot clear replacement",()=>{var leases=new HunterVisionLeases();var oldOwner=new object();var newOwner=new object();leases.Replace(oldOwner,new byte[]{3});leases.Replace(newOwner,new byte[]{3});leases.Release(oldOwner);leases.Release(oldOwner);Check(leases.Contains(3));});
