  Test("Hunter option snapshots are per owner",()=>{OptionItem.All[56411].Value=0;OptionItem.All[56410].Value=20;var a=new Hunter(P(1,CustomRoles.Hunter));OptionItem.All[56411].Value=1;OptionItem.All[56410].Value=60;var b=new Hunter(P(2,CustomRoles.Hunter));Check(!a.CanUseImpostorVentButton()&&b.CanUseImpostorVentButton());a.ApplyGameOptions(null);Eq(20f,AmongUs.GameOptions.AURoleOptions.ShapeshifterCooldown);b.ApplyGameOptions(null);Eq(60f,AmongUs.GameOptions.AURoleOptions.ShapeshifterCooldown);});
