  Test("dead target cancellation does not touch another Hunter",()=>{var a=new Hunter(P(1,CustomRoles.Hunter));var b=new Hunter(P(2,CustomRoles.Hunter));var p=P(5);var dead=P(3);var alive=P(4);bool animate=true;a.CheckShapeshift(dead,ref animate);b.CheckShapeshift(alive,ref animate);dead.Data.IsDead=true;a.OnFixedUpdate(a.Player);b.OnFixedUpdate(b.Player);Eq(1,CustomRoleManager.Attempts);Check(!a.PublicRoleColor&&b.PublicRoleColor);});
