  Test("Professional recycled PlayerId cannot trigger old report",()=>{var pro=Pro();var victim=P(2);pro.Player.Target=victim;PressPro(pro);PlayerCatch.All.Remove(victim);var replacement=P(2);replacement.Data.IsDead=true;LateTask.Drain();Eq(0,replacement.Reports);});
  Test("Professional client cannot invoke special kill",()=>{var pro=Pro();pro.Player.Target=P(2);AmongUsClient.Instance.AmHost=false;Check(!PressPro(pro));Eq(0,CustomRoleManager.Attempts);});
  Test("DoubleKiller vent time restores remaining ability cooldown",()=>{var p=P(1,CustomRoles.DoubleKiller);p.inVent=false;DoubleKiller.RoleInfo.Setup();var dk=new DoubleKiller(p);dk.OnFixedUpdate(p);Time.time=5;p.inVent=true;dk.OnFixedUpdate(p);Time.time=15;p.inVent=false;dk.OnFixedUpdate(p);dk.ApplyGameOptions(null);Eq(25f,AmongUs.GameOptions.AURoleOptions.PhantomCooldown);Eq(1,p.ResetCount);Eq(1,LateTask.Jobs.Count);LateTask.Drain();dk.ApplyGameOptions(null);Eq(30f,AmongUs.GameOptions.AURoleOptions.PhantomCooldown);});
  Test("DoubleKiller ready-before-vent does not gain cooldown",()=>{DoubleKiller.RoleInfo.Setup();var p=P(1,CustomRoles.DoubleKiller);p.inVent=false;var dk=new DoubleKiller(p);dk.OnFixedUpdate(p);Time.time=40;p.inVent=true;dk.OnFixedUpdate(p);Time.time=60;p.inVent=false;dk.OnFixedUpdate(p);Eq(0,p.ResetCount);});
  Test("DoubleKiller vent callback cannot alter later meeting",()=>{DoubleKiller.RoleInfo.Setup();var p=P(1,CustomRoles.DoubleKiller);p.inVent=false;var dk=new DoubleKiller(p);dk.OnFixedUpdate(p);Time.time=5;p.inVent=true;dk.OnFixedUpdate(p);Time.time=15;p.inVent=false;dk.OnFixedUpdate(p);dk.OnStartMeeting();int settings=p.SettingsCount;LateTask.Drain();Eq(settings,p.SettingsCount);dk.ApplyGameOptions(null);Eq(30f,AmongUs.GameOptions.AURoleOptions.PhantomCooldown);});
  Test("DoubleKiller older vent callback cannot clear fresh override",()=>{DoubleKiller.RoleInfo.Setup();var p=P(1,CustomRoles.DoubleKiller);p.inVent=false;var dk=new DoubleKiller(p);dk.OnFixedUpdate(p);Time.time=5;p.inVent=true;dk.OnFixedUpdate(p);Time.time=10;p.inVent=false;dk.OnFixedUpdate(p);var old=LateTask.Jobs[0].Action;Time.time=11;p.inVent=true;dk.OnFixedUpdate(p);Time.time=12;p.inVent=false;dk.OnFixedUpdate(p);old();dk.ApplyGameOptions(null);Eq(24f,AmongUs.GameOptions.AURoleOptions.PhantomCooldown);});
  foreach(string input in new[]{"null","invalid-base64","oversized","factory-null","factory-throw","wrong-mode","missing-logic","missing-game"})Test("Vanilla options invalid import preserves references "+input,()=>{ImportOptionsManager.Instance=new();ImportGameManager.Instance=new();var manager=ImportOptionsManager.Instance;var host=manager.GameHostOptions;var current=manager.CurrentGameOptions;string text="AA==";if(input=="null")text=null;if(input=="invalid-base64")text="!";if(input=="oversized")text=new string('A',1048577);if(input=="factory-null")manager.gameOptionsFactory.Result=null;if(input=="factory-throw")manager.gameOptionsFactory.Throw=true;if(input=="wrong-mode")manager.gameOptionsFactory.Result.Normal=false;if(input=="missing-logic")ImportGameManager.Instance.LogicOptions=null;if(input=="missing-game")ImportGameManager.Instance=null;bool threw=false;try{OptionImportFragment.LoadVanillaOptionsString(text);}catch{threw=true;}Check(threw);Check(ReferenceEquals(host,manager.GameHostOptions)&&ReferenceEquals(current,manager.CurrentGameOptions));});
  Test("Vanilla options valid import applies and syncs once",()=>{ImportOptionsManager.Instance=new();ImportGameManager.Instance=new();var manager=ImportOptionsManager.Instance;var logic=ImportGameManager.Instance.LogicOptions;OptionImportFragment.LoadVanillaOptionsString("AA==");Check(ReferenceEquals(manager.gameOptionsFactory.Result,manager.CurrentGameOptions)&&ReferenceEquals(manager.CurrentGameOptions,manager.GameHostOptions)&&ReferenceEquals(manager.CurrentGameOptions,logic.Value));Eq(1,logic.Sets);Eq(1,logic.Syncs);});
  foreach(bool setFailure in new[]{false,true})Test("Vanilla options rollback on native apply failure "+setFailure,()=>{ImportOptionsManager.Instance=new();ImportGameManager.Instance=new();var manager=ImportOptionsManager.Instance;var logic=ImportGameManager.Instance.LogicOptions;var host=manager.GameHostOptions;var current=manager.CurrentGameOptions;logic.ThrowSet=setFailure;logic.ThrowSync=!setFailure;try{OptionImportFragment.LoadVanillaOptionsString("AA==");throw new Exception("not rejected");}catch(InvalidOperationException){}Check(ReferenceEquals(host,manager.GameHostOptions)&&ReferenceEquals(current,manager.CurrentGameOptions));if(!setFailure)Check(ReferenceEquals(current,logic.Value));});
  Test("Vanilla options rollback failure preserves original exception",()=>{ImportOptionsManager.Instance=new();ImportGameManager.Instance=new();ImportGameManager.Instance.LogicOptions.ThrowSync=true;ImportGameManager.Instance.LogicOptions.ThrowRollback=true;try{OptionImportFragment.LoadVanillaOptionsString("AA==");throw new Exception("not rejected");}catch(InvalidOperationException e){Eq("sync",e.Message);}});
  foreach(string state in new[]{"ended","winner","meeting","blackout"})Test("delayed ghost restoration cannot overwrite final state "+state,()=>{if(state=="winner")CustomWinnerHolder.WinnerTeam=CustomWinner.Crewmate;if(state=="meeting")GameStates.CalledMeeting=true;Check(!FinalGuardFragments.CanRestoreGhost(state=="blackout",state!="ended"));});
  Test("delayed ghost restoration remains valid in task phase",()=>Check(FinalGuardFragments.CanRestoreGhost(false,true)));
  foreach(string value in new[]{"", "<color=#ffffff>name</color>","ffffff-ffffff", "#FFFFFF", "名前と ffffff"})Test("literal log-color replacement preserves previous result "+value,()=>Eq(System.Text.RegularExpressions.Regex.Replace(value,"ffffff","000000"),FinalGuardFragments.LogColor(value)));
  Console.WriteLine($"COMPLETION_RESULT {passed} passed, {failed} failed");Environment.ExitCode=failed==0?0:1;
 }
